(()=>{
  const root=document.getElementById('referralPage');
  if(!root)return;
  const KEY='solCasaReferralDemoV1';
  const source=new URLSearchParams(location.search).get('ref')||'FAMILIA-ANA';
  const initial={shares:0,calculators:0,appointments:0,installs:0};
  const read=()=>{try{return {...initial,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return {...initial}}};
  const write=s=>{try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}};
  const money=n=>new Intl.NumberFormat('es-CR',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
  const fmt=n=>new Intl.NumberFormat('es-CR',{maximumFractionDigits:1}).format(n);
  const appUrl=()=>{const u=new URL(location.href);u.searchParams.set('ref','CASA-ANA');return u.toString()};
  let state=read(),view='family',months=24,bill=110,neighborResult=null,appointmentStage=null;
  const inc=k=>{state[k]=(state[k]||0)+1;write(state);render()};
  function nav(){return `<div class="ref-tabs" role="tablist" aria-label="Vistas del prototipo"><button type="button" data-view="family" role="tab" aria-selected="${view==='family'}">Mi ahorro</button><button type="button" data-view="neighbor" role="tab" aria-selected="${view==='neighbor'}">Soy vecino</button><button type="button" data-view="owner" role="tab" aria-selected="${view==='owner'}">Panel de Andrés</button></div>`}
  function family(){const monthly=110*.70,total=monthly*months;return `<div class="ref-grid"><div><div class="ref-hero"><span class="ref-note">Familia con paneles</span><h2>Tu casa ahorró</h2><div class="ref-money">${money(monthly)} <small style="font-size:14px;color:#d1ded5">este mes</small></div><p>Estimación con el ahorro promedio del caso: 70 % de un recibo mensual de USD 110. Cambia los meses para ver un acumulado de ejemplo.</p></div><article class="ref-card"><h2>Tu ahorro acumulado</h2><div class="ref-stats"><div class="ref-stat"><small>AHORRO DESDE LA INSTALACIÓN</small><strong>${money(total)}</strong></div><label class="ref-stat"><small>MESES DESDE LA INSTALACIÓN · SIMULADO</small><input id="refMonths" type="number" min="1" max="240" value="${months}" style="margin-top:7px;width:100%;border:1px solid #e1e6dc;border-radius:8px;padding:8px"></label></div><div class="ref-banner">Los datos reales de producción los puede leer Sol de Casa del inversor de cada hogar. Este prototipo usa un promedio del caso; no está conectado a esos equipos.</div></article></div><div><article class="ref-card"><span class="ref-note">Comparte sin mostrar tu recibo</span><h2 style="margin-top:9px">Invita a un vecino</h2><p>Comparte el ahorro como una idea útil. El enlace de demostración identifica a esta familia para registrar el referido.</p><div class="ref-hero" style="padding:16px"><b>En mi casa ahorramos cerca de ${money(monthly)} al mes con paneles solares.</b><br><span style="color:#d1ded5;font-size:12px">¿Querés ver cuánto podrías ahorrar vos?</span></div><div class="ref-share"><span class="ref-link" id="refLink">${appUrl()}</span><button class="ref-btn primary" type="button" data-action="share">Compartir</button></div><div class="ref-banner">Si tu vecino agenda, no se entrega una recompensa todavía. Si instala, el ejemplo de recompensa está calculado dentro de la regla de Andrés.</div></article><article class="ref-card"><h3>Si tu vecino instala</h3><p>Recompensa de ejemplo, solo después de la instalación:</p><div class="ref-stats"><div class="ref-stat"><small>LIMPIEZA DE PANELES</small><strong>${money(60)}</strong></div><div class="ref-stat"><small>DESCUENTO EN MANTENIMIENTO</small><strong>${money(100)}</strong></div></div><div class="ref-banner">La visita cuesta unos ${money(133)} por venta referida. Recompensa ${money(160)} + visitas ${money(133)} = <b>${money(293)}</b>, debajo del máximo de ${money(300)}.</div></article></div></div>`}
  function neighbor(){return `<div class="ref-grid"><div class="ref-hero"><span class="ref-note">Tu vecino comparte este enlace</span><h2>Calcula cuánto podrías ahorrar</h2><p>Una estimación sencilla para decidir si vale la pena pedir una visita. No requiere subir ni mostrar tu recibo.</p><div class="ref-banner" style="background:#ffffff18;border-color:#ffffff30;color:#fff">Referido por: <b>${source}</b></div></div><div><article class="ref-card"><h2>Tu recibo de luz</h2><p>Escribe el monto aproximado mensual. El ejemplo usa el 70 % de ahorro promedio indicado en el caso.</p><form class="ref-form" id="neighborCalc"><label>Monto mensual del recibo (USD)<input id="neighborBill" type="number" min="1" step="1" value="${bill}" required></label><button class="ref-btn primary" type="submit">Ver mi estimación</button></form>${neighborResult?`<div class="ref-result" style="margin-top:12px"><b>Ahorro estimado: ${money(neighborResult.monthly)} al mes</b><br>${money(neighborResult.monthly*12)} al año · recuperación simple aproximada en ${fmt(neighborResult.payback)} años con una instalación promedio de ${money(6500)}.<br><span class="ref-muted">Es una aproximación: no incluye financiamiento, cambios de tarifa, techo ni cotización individual.</span><div style="margin-top:12px"><button class="ref-btn primary" type="button" data-action="appointment">Pedir visita técnica</button></div></div>`:''}</article><article class="ref-card"><h3>¿Qué pasa si pides una visita?</h3><div class="ref-steps"><span class="ref-step">1 · Revisamos el techo</span><span class="ref-step">2 · Vemos el recibo</span><span class="ref-step">3 · Recibes una propuesta</span></div><div class="ref-banner">La solicitud es simulada para esta demostración: este sitio no envía datos ni agenda una visita real.</div></article></div></div>`}
  function appointment(){return `<div class="ref-grid"><div class="ref-hero"><span class="ref-note">Paso final · demostración</span><h2>Solicita una visita</h2><p>Andrés puede ver que llegaste por el ahorro compartido por ${source}.</p><div class="ref-money" style="font-size:28px">Tu ahorro estimado: ${money(neighborResult?.monthly??77)}/mes</div></div><div class="ref-card"><form class="ref-form" id="appointmentForm"><label>¿Cómo te llamas?<input name="name" required maxlength="60" placeholder="Tu nombre"></label><label>¿Qué día te conviene?<select name="time"><option>Entre semana por la mañana</option><option>Entre semana por la tarde</option><option>Sábado</option></select></label><button class="ref-btn primary" type="submit">Enviar solicitud de demostración</button></form><p class="ref-muted">No escribas datos reales: la solicitud solo actualiza este prototipo en tu navegador.</p></div></div>`}
  function booked(){return `<div class="ref-card"><span class="ref-note">Solicitud simulada registrada</span><h2 style="margin-top:10px">¡Listo! El equipo tendría una solicitud para revisar el techo.</h2><p>El origen queda marcado como <b>${source}</b>. En una implementación real, Sol de Casa confirmaría la hora y se pondría en contacto contigo.</p><div class="ref-banner warn">Esto no creó una cita real ni envió información fuera de este navegador.</div><button class="ref-btn primary" type="button" data-action="simulateInstall">Simular que el vecino instala</button><button class="ref-btn" type="button" data-view="family" style="margin-left:7px">Volver a Mi ahorro</button></div>`}
  function owner(){const bars=[['Tarjetas compartidas',state.shares],['Calculadoras completadas',state.calculators],['Visitas solicitadas',state.appointments],['Instalaciones simuladas',state.installs]],max=Math.max(1,...bars.map(x=>x[1]));return `<article class="ref-card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:start;flex-wrap:wrap"><div><span class="ref-note sim">Datos simulados / de referencia</span><h2 style="margin-top:8px">Lo que pasa después de instalar</h2><p>El panel separa cifras del caso de interacciones hechas en esta demostración. No representa resultados reales del piloto.</p></div><button type="button" class="ref-btn" data-action="resetDemo">Reiniciar demo</button></div><div class="ref-flow">${bars.map(([label,n])=>`<div>${label}<strong>${n}</strong><div class="ref-bar"><i style="width:${Math.min(100,n/max*100)}%"></i></div></div>`).join('')}</div><p class="ref-muted">Cada clic de prueba se guarda únicamente en este navegador. Borrar los datos no afecta el archivo del caso.</p></article><div class="ref-grid"><article class="ref-card"><h3>Referencia: familias actuales</h3><table class="ref-table"><tr><th>Dato del caso</th><th>Valor</th></tr><tr><td>Familias con paneles</td><td>420</td></tr><tr><td>Saben su ahorro mensual</td><td>25 % · aprox. 105</td></tr><tr><td>Enseñaron su recibo a alguien</td><td>40 % · aprox. 168</td></tr><tr><td>Refieren sin que se les pida</td><td>8 % anual · aprox. 34/año</td></tr><tr><td>Leads espontáneos por mes</td><td>420 × 8 % ÷ 12 = 2,8</td></tr></table></article><article class="ref-card"><h3>Referencia: web actual</h3><table class="ref-table"><tr><th>Paso</th><th>Personas</th></tr><tr><td>Visitan la página</td><td>100</td></tr><tr><td>Abren el formulario</td><td>14</td></tr><tr><td>Dejan sus datos</td><td>6</td></tr></table><p class="ref-muted">La mayor caída es de visita web a apertura de formulario: 86 de cada 100 no lo abren. La experiencia del referido prueba una entrada más clara, con estimación antes de pedir una visita.</p></article></div><article class="ref-card"><h3>Diseño del piloto de 50 familias</h3><p><b>25 reciben</b> su ahorro mensual con botón para compartir y <b>25 siguen igual</b>. Medimos leads referidos en 2 meses y vigilamos que el cierre de visitas no baje. La muestra pequeña sirve como señal inicial; no prueba por sí sola causalidad.</p><div class="ref-banner warn">Métricas del piloto todavía no existen. Los contadores superiores reflejan solo lo que hagas ahora en la demo.</div></article>`}
  function render(){const content=view==='owner'?owner():view==='neighbor'?(appointmentStage==='booked'?booked():appointmentStage==='form'?appointment():neighbor()):family();root.innerHTML=`<div class="ref-shell"><header class="ref-head"><div><span class="ref-kicker">Prototipo de growth · Caso C</span><h1>El ahorro que se comparte</h1><p>La familia entiende su ahorro; el vecino recibe una estimación útil; Sol de Casa mide el camino completo.</p></div><span class="ref-note sim">Prototipo de demostración</span></header>${nav()}${content}<footer class="ref-foot">Caso de ficción educativa. Datos de interacción y hogares de ejemplo están identificados como simulados. La calculadora usa cifras promedio del caso y no sustituye una evaluación del techo.</footer></div>`}
  root.addEventListener('click',async e=>{const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;if(view==='neighbor'){if(appointmentStage==='booked')appointmentStage=null;if(neighborResult===false)neighborResult=null}render();return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'share':try{if(navigator.share){await navigator.share({title:'Ahorro solar',text:'En mi casa ahorramos cerca de USD 77 al mes con paneles solares. ¿Cuánto podrías ahorrar vos?',url:appUrl()});inc('shares')}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(appUrl());inc('shares');alert('Enlace de demostración copiado.')}else{window.prompt('Copia el enlace de demostración:',appUrl())}}catch{}break;case'appointment':view='neighbor';appointmentStage='form';render();break;case'simulateInstall':inc('installs');alert('Cierre simulado. No es una venta real.');break;case'resetDemo':state={...initial};write(state);render();break}});
  root.addEventListener('input',e=>{if(e.target.id==='neighborBill')bill=Math.max(1,Number(e.target.value)||1)});
  root.addEventListener('change',e=>{if(e.target.id==='refMonths'){months=Math.max(1,Math.min(240,Number(e.target.value)||1));render()}});
  root.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='neighborCalc'){bill=Math.max(1,Number(document.getElementById('neighborBill').value)||1);neighborResult={monthly:bill*.70,payback:6500/(bill*.70*12)};inc('calculators');return}if(e.target.id==='appointmentForm'){inc('appointments');appointmentStage='booked';render()}});
  window.SolCasaReferralDemo={getState:()=>({...state}),getView:()=>view};
  render();
})();
